"use client";
import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useAdminAuth } from "@/components/admin/AdminAuthProvider";
import { useConfirm } from "@/components/admin/ConfirmProvider";
import { CacheRecord, deleteCache, getCache, updateCache } from "@/lib/adminCache";
import { CacheFields } from "@/components/admin/CacheForm";
export default function EditCache() { const { category, id } = useParams<{ category: string; id: string }>(); const router = useRouter(); const { handleApiError } = useAdminAuth(); const confirm = useConfirm(); const [p, setP] = useState<CacheRecord | null>(null); const [error, setError] = useState(""); useEffect(() => { getCache(category as "engine" | "transmission", Number(id)).then(setP).catch(e => setError(handleApiError(e) || "Introuvable")); }, [category, id, handleApiError]); if (error) return <p className="mx-auto max-w-3xl p-8 text-red-700">{error}</p>; if (!p) return <p className="mx-auto max-w-3xl p-8 text-brand-text-muted">Chargement…</p>; const set = (k: string, v: string) => setP({ ...p, [k]: k.includes("year") ? Number(v) : v }); const submit = async (e: React.FormEvent) => { e.preventDefault(); try { await updateCache(p.category, p.id, p); router.replace(`/admin/cache?category=${p.category}`); } catch (e) { setError(handleApiError(e) || "Erreur"); } }; const remove = async () => { if (await confirm("Cette règle sera supprimée.", { title: "Supprimer ?", confirmLabel: "Supprimer", danger: true })) { await deleteCache(p.category, p.id); router.replace(`/admin/cache?category=${p.category}`); } }; return <form onSubmit={submit} className="mx-auto max-w-3xl px-4 py-8 sm:px-6"><div className="mb-6"><p className="text-xs font-bold uppercase tracking-[0.2em] text-brand-orange">Référentiel véhicule</p><h1 className="mt-2 text-3xl font-bold text-brand-text">Modifier une règle</h1></div><div className="rounded-2xl border border-brand-border bg-brand-surface p-5 shadow-sm sm:p-7"><CacheFields value={p} onChange={set} edit /><div className="mt-6 flex flex-wrap gap-3 border-t border-brand-border pt-6"><button className="rounded-xl bg-brand-orange px-5 py-3 font-bold text-white hover:bg-brand-orange-hover">Enregistrer</button><button type="button" onClick={remove} className="rounded-xl border border-red-300 px-5 py-3 font-bold text-red-700 hover:bg-red-50">Supprimer</button></div>{error && <p className="mt-4 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</p>}</div></form>; }
